  prerequisites: z.array(z.string().trim().min(1)).default([]),
  dependencies: z.array(z.string().regex(/^[a-z][a-z0-9-]{2,79}$/)).default([]),
  decisionRules: z.array(z.string().trim().min(1)).default([]),
